package com.example.dsatracker.controller;import com.example.dsatracker.dto.TagRequestDTO;import com.example.dsatracker.dto.TagResponseDTO;import com.example.dsatracker.service.TagService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController@RequestMapping("/tags")public class TagController {    private final TagService service;    public TagController(TagService service) {        this.service = service;    }    @PostMapping    public ResponseEntity<TagResponseDTO> createTag(            @Valid @RequestBody TagRequestDTO request) {        TagResponseDTO response = service.createTag(request);        return ResponseEntity                .status(HttpStatus.CREATED)                .body(response);    }    @GetMapping    public ResponseEntity<List<TagResponseDTO>> getAllTags() {        return ResponseEntity.ok(service.getAllTags());    }    @GetMapping("/{id}")    public ResponseEntity<TagResponseDTO> getTagById(            @PathVariable Long id) {        return ResponseEntity.ok(service.getTagById(id));    }}